// NestJS service
async updateName(userId: string, name: string) {
  await this.primary.query('UPDATE users SET name = $1 WHERE id = $2', [name, userId]);
}

async getProfile(userId: string) {
  // round-robin over read replicas
  return this.replicaPool.query('SELECT * FROM users WHERE id = $1', [userId]);
}
